"""Strict request syntax and normalized full-width addresses, protocol 2."""
import ipaddress
import json
import re

MAX_INPUT = 16 * 1024 * 1024


class Invalid(ValueError):
    pass


def unique_object(pairs):
    obj = {}
    for key, value in pairs:
        if key in obj:
            raise Invalid("duplicate key")
        obj[key] = value
    return obj


def nonfinite(_):
    raise Invalid("nonfinite JSON")


def keys(value, names):
    if type(value) is not dict or set(value) != set(names):
        raise Invalid("object shape")


def array(value):
    if type(value) is not list:
        raise Invalid("array required")
    return value


def integer(value, low, high):
    if type(value) is not int or not low <= value <= high:
        raise Invalid("integer range")
    return value


def address(value):
    if (type(value) is not str or not 1 <= len(value) <= 64
            or re.fullmatch(r"[0-9a-fA-F:]+", value) is None):
        raise Invalid("IPv6 address")
    try:
        return int(ipaddress.IPv6Address(value))
    except ValueError as exc:
        raise Invalid("IPv6 address") from exc


def prefix(value):
    if type(value) is not str or len(value) > 64 or value.count("/") != 1:
        raise Invalid("prefix")
    addr, length = value.split("/")
    if re.fullmatch(r"0|[1-9][0-9]*", length) is None:
        raise Invalid("prefix length")
    length = integer(int(length), 0, 128)
    size = 1 << (128 - length)
